const n="// 传统沙箱脚本 - 使用 registerFunction 注册函数\r\n// 上下文变量：$api, $route, $data, $el, $query, $queryAll, $rebindRules, $refreshData, $dataSet, $call 都已注入\r\n// 额外注入：ElMessage, h\r\n\r\n// 添加日志\r\nfunction addLog(message, type = 'info') {\r\n  const pageData = $data()\r\n  const timestamp = new Date().toLocaleTimeString()\r\n\r\n  pageData.apiLog.unshift({\r\n    time: timestamp,\r\n    message,\r\n    type\r\n  })\r\n\r\n  // 限制日志条数\r\n  if (pageData.apiLog.length > 50) {\r\n    pageData.apiLog = pageData.apiLog.slice(0, 50)\r\n  }\r\n\r\n  console.log(`[${timestamp}] ${message}`)\r\n}\r\n\r\n// 页面初始化\r\nconsole.log('📋 Form-Create API演示页面已加载 (传统沙箱执行)');\r\nconsole.log('📦 页面数据:', $data);\r\n\r\n// 全局变量\r\nlet emailDisabled = false\r\nlet phoneHidden = false\r\n\r\n// 注册页面函数\r\nregisterFunction('handleGetAllValues', function() {\r\n  const api = $api()\r\n  if (!api) {\r\n    ElMessage.error('API 未初始化')\r\n    return\r\n  }\r\n\r\n  const values = api.formData()\r\n  addLog(`📊 获取所有值: ${JSON.stringify(values)}`, 'success')\r\n  ElMessage.success('已输出到控制台')\r\n  console.log('表单数据:', values)\r\n});\r\n\r\nregisterFunction('handleSetValues', function() {\r\n  const api = $api()\r\n  if (!api) return\r\n\r\n  api.setValue({\r\n    username: 'demo_user',\r\n    email: 'demo@example.com',\r\n    phone: '13800138000',\r\n    description: '这是通过 API 设置的值'\r\n  })\r\n\r\n  addLog('✏️ 批量设置值成功', 'success')\r\n  ElMessage.success('已批量设置表单值')\r\n});\r\n\r\nregisterFunction('handleValidate', function() {\r\n  const api = $api()\r\n  if (!api) return\r\n\r\n  addLog('🔍 开始验证表单...', 'info')\r\n\r\n  api.validate((valid) => {\r\n    if (valid) {\r\n      addLog('✅ 表单验证通过', 'success')\r\n      ElMessage.success('表单验证通过')\r\n    } else {\r\n      addLog('❌ 表单验证失败', 'error')\r\n      ElMessage.error('表单验证失败')\r\n    }\r\n  })\r\n});\r\n\r\nregisterFunction('handleReset', function() {\r\n  const api = $api()\r\n  if (!api) return\r\n\r\n  api.resetFields()\r\n  addLog('🔄 表单已重置', 'info')\r\n  ElMessage.success('表单已重置')\r\n});\r\n\r\nregisterFunction('handleClearValidate', function() {\r\n  const api = $api()\r\n  if (!api) return\r\n\r\n  api.clearValidateState()\r\n  addLog('🧹 验证状态已清除', 'info')\r\n  ElMessage.success('验证状态已清除')\r\n});\r\n\r\nregisterFunction('handleToggleAdvanced', function() {\r\n  const pageData = $data()\r\n  pageData.showAdvanced = !pageData.showAdvanced\r\n\r\n  addLog(`🔧 高级选项: ${pageData.showAdvanced ? '显示' : '隐藏'}`, 'info')\r\n  ElMessage.info(`高级选项已${pageData.showAdvanced ? '显示' : '隐藏'}`)\r\n});\r\n\r\nregisterFunction('handleDisableEmail', function() {\r\n  const api = $api()\r\n  if (!api) return\r\n\r\n  emailDisabled = !emailDisabled\r\n\r\n  // 方式1：使用 disabled() 方法\r\n  api.disabled(emailDisabled, 'email')\r\n\r\n  // 方式2：使用 updateRule() 方法\r\n  // api.updateRule('email', {\r\n  //   props: { disabled: emailDisabled }\r\n  // })\r\n\r\n  addLog(`🔒 邮箱字段: ${emailDisabled ? '已禁用' : '已启用'}`, 'warning')\r\n  ElMessage.info(`邮箱字段已${emailDisabled ? '禁用' : '启用'}`)\r\n});\r\n\r\nregisterFunction('handleHidePhone', function() {\r\n  const api = $api()\r\n  if (!api) return\r\n\r\n  phoneHidden = !phoneHidden\r\n  api.hidden(phoneHidden, 'phone')\r\n\r\n  addLog(`👁️ 电话字段: ${phoneHidden ? '已隐藏' : '已显示'}`, 'warning')\r\n  ElMessage.info(`电话字段已${phoneHidden ? '隐藏' : '显示'}`)\r\n});\r\n\r\nregisterFunction('handleUpdatePlaceholder', function() {\r\n  const api = $api()\r\n  if (!api) return\r\n\r\n  const timestamp = new Date().toLocaleTimeString()\r\n\r\n  api.updateRule('username', {\r\n    props: {\r\n      placeholder: `更新于 ${timestamp}`\r\n    }\r\n  })\r\n\r\n  addLog(`📝 已更新用户名占位符: ${timestamp}`, 'success')\r\n  ElMessage.success('占位符已更新')\r\n});\r\n\r\nregisterFunction('handleUserTypeChange', function(userType) {\r\n  const api = $api()\r\n  if (!api) return\r\n\r\n  addLog(`🔄 用户类型切换: ${userType}`, 'info')\r\n\r\n  if (userType === 'company') {\r\n    // 企业用户：显示公司信息\r\n    api.hidden(false, ['companyName_field', 'taxNumber_field'])\r\n    api.hidden(true, 'personalId_field')\r\n\r\n    addLog('👔 显示企业字段，隐藏个人字段', 'success')\r\n  } else {\r\n    // 个人用户：显示身份证号\r\n    api.hidden(true, ['companyName_field', 'taxNumber_field'])\r\n    api.hidden(false, 'personalId_field')\r\n\r\n    addLog('👤 显示个人字段，隐藏企业字段', 'success')\r\n  }\r\n});\r\n\r\nregisterFunction('RenderApiLog', function() {\r\n  const pageData = $data()\r\n  const logs = pageData.apiLog || []\r\n\r\n  if (logs.length === 0) {\r\n    return h('div', { style: 'color: #999; textAlign: center; padding: 20px' }, '暂无日志')\r\n  }\r\n\r\n  return h('div', logs.map(log => {\r\n    const colors = {\r\n      info: '#409EFF',\r\n      success: '#67C23A',\r\n      warning: '#E6A23C',\r\n      error: '#F56C6C'\r\n    }\r\n\r\n    return h('div', {\r\n      style: {\r\n        marginBottom: '8px',\r\n        padding: '8px',\r\n        background: '#fff',\r\n        borderRadius: '4px',\r\n        borderLeft: `3px solid ${colors[log.type] || colors.info}`\r\n      }\r\n    }, [\r\n      h('span', { style: 'color: #999; marginRight: 10px' }, log.time),\r\n      h('span', { style: { color: colors[log.type] || colors.info } }, log.message)\r\n    ])\r\n  }))\r\n});\r\n\r\nregisterFunction('__init__', function() {\r\n  addLog('🚀 页面初始化完成', 'success')\r\n  addLog('💡 点击上方按钮测试 API', 'info')\r\n\r\n  const api = $api()\r\n  if (api) {\r\n    // 监听字段值变化\r\n    api.on('change', (field, value) => {\r\n      addLog(`🔔 字段 \"${field}\" 变化: ${JSON.stringify(value)}`, 'info')\r\n    })\r\n\r\n    addLog('✅ 已注册 change 事件监听', 'success')\r\n  }\r\n});\r\n";export{n as default};
